REPLACE = {'frontend/src/cards/ForecastCard.jsx': {'before': 'e29fca9b8039c1771fc7e766786a2e0013f8d4160a65b17d6b6a75c7130e5501', 'after': 'import { Badge, Card } from \'../ui/primitives\';\nimport { HowMeasured } from \'../ui/viz\';\nimport { LineChart } from \'../ui/charts\';\nimport \'./exposure.css\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Forward exposure: where modelled surface particles go after the image.\n * Modelled exposure and arrival intervals, never predicted damage; the\n * forcing mode is shown verbatim so a retrospective field is not mistaken\n * for an operational forecast.\n */\nconst hhmm = (s) => s.replace(\'T\', \' \').replace(\':00+00:00\', \' UTC\');\n\nconst pct = (v) => `${Math.round(v * 100)}%`;\nconst TONES = [\'cyan\', \'green\', \'orange\'];\n\nexport default function ForecastCard({ forecast }) {\n  if (!forecast) return null;\n  const hs = forecast.horizons;\n  const xs = hs.map((h) => `+${h.horizon_hours} h`);\n  const spreadMax = Math.ceil(Math.max(...hs.map((h) => h.envelope_area_km2)) / 100) * 100;\n  const areas = hs[0]?.sensitive_area_exposure.map((a) => a.name) ?? [];\n  const share = [\n    ...areas.map((name, k) => ({ name, tone: TONES[k % TONES.length],\n      values: hs.map((h) => h.sensitive_area_exposure.find((a) => a.name === name)?.modelled_particle_fraction ?? 0) })),\n    ...(hs.some((h) => h.modelled_shoreline_fraction != null)\n      ? [{ name: \'Shoreline\', tone: \'grey\', values: hs.map((h) => h.modelled_shoreline_fraction ?? 0) }] : []),\n  ];\n  const shareMax = Math.max(0.1, Math.ceil(Math.max(...share.flatMap((x) => x.values)) * 10) / 10);\n  // first contact is recorded per area; the chip names the earliest area reached\n  const byArea = Object.entries(forecast.first_modelled_sensitive_contact_h ?? {}).filter(([, h]) => h != null)\n    .sort((x, y) => x[1] - y[1]);\n  const firstArea = byArea[0] ?? null, firstShore = forecast.first_modelled_shoreline_contact_h;\n  const last = hs[hs.length - 1]?.horizon_hours;\n  return (\n    <Card title="Forward Exposure" badge={<Badge tone="warning">modelled</Badge>}\n          caption="Where the oil is modelled to drift after the image.">\n      <div className="fx-chips">\n        <span className={`fx-chip${firstArea != null ? \' is-warn\' : \'\'}`}>\n          {firstArea ? <>Reaches the {firstArea[0].replace(\' (synthetic)\', \'\').toLowerCase()} by <b>+{firstArea[1]} h</b></> : <>No sensitive-area contact within {last} h</>}</span>\n        <span className={`fx-chip${firstShore != null ? \' is-warn\' : \'\'}`}>\n          {firstShore != null ? <>Reaches the shoreline by <b>+{firstShore} h</b></> : <>No shoreline contact within {last} h</>}</span>\n        <span className="fx-chip is-mode">{forecast.forcing_mode.split(\' — \')[0]} — not an operational forecast</span>\n      </div>\n      <div className="fx-charts">\n        <figure className="fx-fig">\n          <figcaption><b>Modelled spread</b><span>{hs.map((h) => `${Math.round(h.envelope_area_km2)}`).join(\' → \')} km²</span></figcaption>\n          <LineChart xs={xs} yMax={spreadMax} yFormat={(v) => `${Math.round(v)}`}\n                     series={[{ name: \'Modelled spread (km²)\', tone: \'accent\', area: true, values: hs.map((h) => h.envelope_area_km2) }]}\n                     ariaLabel={`Modelled spread: ${hs.map((h) => `${h.envelope_area_km2} square kilometres at plus ${h.horizon_hours} hours`).join(\', \')}`} />\n        </figure>\n        <figure className="fx-fig">\n          <figcaption><b>Share of modelled oil</b>\n            <span className="fx-legend">{share.map((x) => <i key={x.name} className={`tone-${x.tone}`}>{x.name.replace(\' (synthetic)\', \'\')}</i>)}</span>\n          </figcaption>\n          <LineChart xs={xs} yMax={shareMax} yFormat={pct} series={share}\n                     ariaLabel={share.map((x) => `${x.name}: ${x.values.map((v) => pct(v)).join(\', \')}`).join(\'; \')} />\n        </figure>\n      </div>\n      <HowMeasured>\n        <dl>\n          <dt>Horizon</dt><dd>{C.horizon} {hs.map((h) => `+${h.horizon_hours} h is ${hhmm(h.valid_utc)}`).join(\'; \')}.</dd>\n          <dt>Modelled spread</dt><dd>{C.envelopeArea}</dd>\n          <dt>Shoreline</dt><dd>{C.shoreline}</dd>\n          <dt>Sensitive areas</dt><dd>{C.exposure} Areas are synthetic.</dd>\n          <dt>Forcing</dt><dd>{forecast.forcing_mode}. {forecast.n_ensemble_variants} forcing settings.</dd>\n          <dt>What this is and is not</dt><dd>{forecast.interpretation_note}</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n'}, 'frontend/src/cards/NextObservationCard.jsx': {'before': '0d7bc7254b1431a9b43aad89964500088baad47bec29347466407bb2c88ccdd6', 'after': 'import { Badge, Card, EmptyState } from \'../ui/primitives\';\nimport { HowMeasured } from \'../ui/viz\';\nimport { BarTimeline } from \'../ui/charts\';\nimport \'./nextObservation.css\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Next observation: which future image would best separate the two leading\n * explanations. Reads the artifact\'s own recommended_window rather than\n * re-deriving it. Recommends evidence; it does not task a satellite.\n */\nconst hhmm = (s) => s.replace(\'T\', \' \').replace(\':00+00:00\', \' UTC\');\n\n// closing: shown as the last card of a case, framed as what to check next\nexport default function NextObservationCard({ nextObs, closing = false }) {\n  const frame = closing ? { eyebrow: \'What to check next\', className: \'is-closing\' } : {};\n  if (!nextObs) return null;\n  if (!nextObs.applicable) {\n    return (\n      <Card title="Next Observation" badge={<Badge>not applicable</Badge>} {...frame}>\n        <EmptyState>Not applicable for this incident: {nextObs.reason}</EmptyState>\n      </Card>\n    );\n  }\n  const rec = nextObs.recommended_window;\n  const A = nextObs.hypothesis_a.vessel_key, B = nextObs.hypothesis_b.vessel_key;\n  return (\n    <Card title="Next Observation" badge={<Badge tone="warning">advisory</Badge>} {...frame}\n          caption={`When one more image would best tell ${A} and ${B} apart.`}>\n      <div className="no">\n        <div className="no-hero">\n          <span className="no-eyebrow">Recommended window</span>\n          <span className="no-big">+{rec.horizon_hours}<small> h</small></span>\n          <span className="no-time">{hhmm(rec.valid_utc)}</span>\n          <div className="no-facts">\n            <span><b>{Math.round(rec.disagreement_score * 100)}%</b> disagreement</span>\n            <span><b>{rec.predicted_overlap_iou.toFixed(2)}</b> predicted overlap</span>\n          </div>\n        </div>\n        <figure className="no-fig">\n          <figcaption>How differently the two explanations predict the slick, by window</figcaption>\n          <BarTimeline highlight={rec.horizon_hours} format={(v) => `${Math.round(v * 100)}%`}\n                       bars={nextObs.windows.map((w) => ({ key: w.horizon_hours, label: `+${w.horizon_hours} h`, value: w.disagreement_score }))}\n                       ariaLabel={`Disagreement by window: ${nextObs.windows.map((w) => `plus ${w.horizon_hours} hours ${Math.round(w.disagreement_score * 100)} percent`).join(\', \')}; recommended plus ${rec.horizon_hours} hours`} />\n        </figure>\n      </div>\n      <p className="no-foot">Recommends which evidence would be most telling; it does not task a satellite.</p>\n      <HowMeasured>\n        <dl>\n          <dt>Recommended window</dt><dd>{C.recommended}</dd>\n          <dt>Disagreement</dt><dd>{C.disagreement}</dd>\n          <dt>Predicted overlap</dt><dd>{C.overlapIou}</dd>\n          <dt>Schedule</dt><dd>{rec.schedule_status}.</dd>\n          <dt>What this is and is not</dt><dd>{nextObs.scope_note} {nextObs.method_note}</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n'}}
NEW = {'frontend/src/cards/exposure.css': '.fx-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: var(--space-4); }\n.fx-chip { padding: 5px 11px; border-radius: 999px; font-size: var(--font-size-xs); color: var(--label-1); background: var(--fill-pressed); }\n.fx-chip b { font-variant-numeric: tabular-nums; }\n.fx-chip.is-warn { color: var(--status-orange); background: rgba(255, 159, 10, 0.12); }\n.fx-chip.is-mode { color: var(--label-2); background: transparent; box-shadow: inset 0 0 0 0.5px var(--separator-strong); }\n.fx-charts { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-5); }\n.fx-fig { margin: 0; padding: 14px 14px 8px; border-radius: 14px; background: var(--fill-pressed); }\n.fx-fig figcaption { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 6px;\n                     font-size: var(--font-size-xs); color: var(--label-2); }\n.fx-fig figcaption b { font-size: var(--font-size-sm); color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.fx-legend { display: flex; gap: 10px; flex-wrap: wrap; }\n.fx-legend i { font-style: normal; display: inline-flex; align-items: center; gap: 5px; }\n.fx-legend i::before { content: ""; width: 10px; height: 2.5px; border-radius: 2px; background: currentColor; }\n.fx-legend i.tone-cyan { color: #64d2ff; } .fx-legend i.tone-green { color: #30d158; } .fx-legend i.tone-orange { color: #ff9f0a; }\n.fx-legend i.tone-grey { color: var(--label-3); }\n@media (max-width: 900px) { .fx-charts { grid-template-columns: 1fr; } }\n', 'frontend/src/cards/nextObservation.css': '.no { display: grid; grid-template-columns: minmax(170px, 0.7fr) minmax(0, 1.6fr); gap: var(--space-6); align-items: end; }\n.no-hero { display: flex; flex-direction: column; }\n.no-eyebrow { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.07em; color: var(--label-2); }\n.no-big { margin-top: 4px; font-family: var(--font-display); font-size: 56px; font-weight: 600; letter-spacing: -0.04em; line-height: 1;\n          background: linear-gradient(90deg, #0a84ff, #64d2ff); -webkit-background-clip: text; background-clip: text; color: transparent; }\n.no-big small { font-size: 22px; letter-spacing: 0; }\n.no-time { margin-top: 6px; font-family: var(--font-mono); font-size: var(--font-size-xs); color: var(--label-2); }\n.no-facts { display: flex; flex-direction: column; gap: 4px; margin-top: 14px; font-size: var(--font-size-sm); color: var(--label-2); }\n.no-facts b { color: var(--label-1); font-variant-numeric: tabular-nums; }\n.no-fig { margin: 0; padding: 14px 16px 10px; border-radius: 14px; background: var(--fill-pressed); }\n.no-fig figcaption { margin-bottom: 10px; font-size: var(--font-size-xs); color: var(--label-2); }\n.no-foot { margin: var(--space-4) 0 0; font-size: var(--font-size-sm); color: var(--label-2); }\n@media (max-width: 900px) { .no { grid-template-columns: 1fr; } }\n', 'frontend/src/ui/charts.css': '/* line chart */\n.lc { width: 100%; height: auto; overflow: visible; }\n.lc-grid { stroke: var(--separator); stroke-width: 0.6; }\n.lc-ytick { font-size: 9px; fill: var(--label-3); text-anchor: end; font-family: var(--font-body); font-variant-numeric: tabular-nums; }\n.lc-xtick { font-size: 9.5px; fill: var(--label-2); text-anchor: middle; font-family: var(--font-body); }\n.lc-line { fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 100; stroke-dashoffset: 100;\n           animation: lc-draw 1100ms cubic-bezier(0.22, 1, 0.36, 1) forwards; animation-delay: calc(200ms + var(--k) * 140ms); }\n.lc-area { opacity: 0; animation: lc-fade 700ms ease forwards; animation-delay: calc(700ms + var(--k) * 140ms); }\n.lc-dot { stroke-width: 2; opacity: 0; animation: lc-pop 380ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards;\n          animation-delay: calc(500ms + var(--k) * 140ms + var(--i) * 120ms); transform-box: fill-box; transform-origin: center; }\n.lc-dot:hover { r: 5.2; }\n.tone-accent .lc-line { stroke: #0a84ff; } .tone-accent .lc-dot { fill: #0a84ff; stroke: var(--card-bg, #fff); }\n.tone-cyan .lc-line { stroke: #64d2ff; } .tone-cyan .lc-dot { fill: #64d2ff; stroke: var(--card-bg, #fff); }\n.tone-green .lc-line { stroke: #30d158; } .tone-green .lc-dot { fill: #30d158; stroke: var(--card-bg, #fff); }\n.tone-orange .lc-line { stroke: #ff9f0a; } .tone-orange .lc-dot { fill: #ff9f0a; stroke: var(--card-bg, #fff); }\n.tone-grey .lc-line { stroke: var(--label-3); stroke-dasharray: 4 3; animation: none; stroke-dashoffset: 0; } .tone-grey .lc-dot { fill: var(--label-3); stroke: var(--card-bg, #fff); }\n@keyframes lc-draw { to { stroke-dashoffset: 0; } }\n@keyframes lc-fade { to { opacity: 1; } }\n@keyframes lc-pop { from { opacity: 0; transform: scale(0); } to { opacity: 1; transform: scale(1); } }\n\n/* bar timeline */\n.bt { display: flex; align-items: stretch; gap: 10px; }\n.bt-col { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 6px; min-width: 0; }\n.bt-val { font-size: var(--font-size-xs); font-variant-numeric: tabular-nums; color: var(--label-2);\n          opacity: 0; animation: lc-fade 400ms ease forwards; animation-delay: calc(600ms + var(--i) * 70ms); }\n.bt-bar { width: 100%; max-width: 46px; height: calc(var(--h) * 100% - 40px); min-height: 4px; border-radius: 8px 8px 4px 4px;\n          background: var(--fill-pressed); transform-origin: bottom; animation: bt-grow 700ms cubic-bezier(0.22, 1.2, 0.36, 1) backwards;\n          animation-delay: calc(150ms + var(--i) * 70ms); }\n.bt-lab { font-size: var(--font-size-xs); color: var(--label-2); white-space: nowrap; }\n.bt-col.is-on .bt-bar { background: linear-gradient(180deg, #64d2ff, #0a84ff); box-shadow: 0 0 18px rgba(10, 132, 255, 0.45); }\n.bt-col.is-on .bt-val, .bt-col.is-on .bt-lab { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n@keyframes bt-grow { from { transform: scaleY(0); } }\n\n@media (prefers-reduced-motion: reduce) {\n  .lc-line { animation: none; stroke-dashoffset: 0; } .lc-area, .lc-dot, .bt-val { animation: none; opacity: 1; } .bt-bar { animation: none; }\n}\n', 'frontend/src/ui/charts.jsx': 'import { useId } from \'react\';\nimport \'./charts.css\';\n\n/**\n * Small, quiet SVG charts: lines that draw in, points you can hover for their\n * value, and bars that grow. They only draw values passed in from artifacts.\n */\n\n/** A line (with optional soft area) over a few labelled x positions. */\nexport function LineChart({ xs, series, yMax, yFormat = (v) => v, height = 150, ariaLabel }) {\n  const gid = useId().replace(/:/g, \'\');\n  const W = 420, H = height, L = 38, R = 14, T = 12, B = 26;\n  const X = (i) => L + (xs.length === 1 ? 0.5 : i / (xs.length - 1)) * (W - L - R);\n  const Y = (v) => T + (1 - v / (yMax || 1)) * (H - T - B);\n  const ticks = [0, yMax / 2, yMax];\n  return (\n    <svg className="lc" viewBox={`0 0 ${W} ${H}`} role="img" aria-label={ariaLabel}>\n      <defs>\n        {/* the area fades from the line down to nothing */}\n        <linearGradient id={`lcf-${gid}`} x1="0" y1="0" x2="0" y2="1">\n          <stop offset="0" stopColor="#0a84ff" stopOpacity="0.32" />\n          <stop offset="1" stopColor="#0a84ff" stopOpacity="0" />\n        </linearGradient>\n      </defs>\n      {ticks.map((t) => (\n        <g key={t}><line x1={L} x2={W - R} y1={Y(t)} y2={Y(t)} className="lc-grid" />\n          <text x={L - 6} y={Y(t) + 3} className="lc-ytick">{yFormat(t)}</text></g>\n      ))}\n      {xs.map((x, i) => <text key={x} x={X(i)} y={H - 8} className="lc-xtick">{x}</text>)}\n      {series.map((s, si) => {\n        const pts = s.values.map((v, i) => [X(i), Y(v ?? 0)]);\n        const d = pts.map((p, i) => `${i ? \'L\' : \'M\'}${p[0]},${p[1]}`).join(\' \');\n        return (\n          <g key={s.name} className={`lc-series tone-${s.tone ?? \'accent\'}`} style={{ \'--k\': si }}>\n            {s.area && <path d={`${d} L${pts[pts.length - 1][0]},${Y(0)} L${pts[0][0]},${Y(0)} Z`} className="lc-area" fill={`url(#lcf-${gid})`} />}\n            <path d={d} className="lc-line" pathLength="100" />\n            {pts.map((p, i) => (\n              <circle key={i} cx={p[0]} cy={p[1]} r="3.6" className="lc-dot" style={{ \'--i\': i }}>\n                <title>{`${s.name} at ${xs[i]}: ${yFormat(s.values[i] ?? 0)}`}</title>\n              </circle>\n            ))}\n          </g>\n        );\n      })}\n    </svg>\n  );\n}\n\n/** Vertical bars over labelled windows; one can be highlighted. */\nexport function BarTimeline({ bars, highlight, format = (v) => v, height = 140, ariaLabel }) {\n  const max = Math.max(...bars.map((b) => b.value), 1e-9);\n  return (\n    <div className="bt" role="img" aria-label={ariaLabel} style={{ height }}>\n      {bars.map((b, i) => (\n        <div key={b.key} className={`bt-col${b.key === highlight ? \' is-on\' : \'\'}`} style={{ \'--i\': i }}>\n          <span className="bt-val">{format(b.value)}</span>\n          <div className="bt-bar" style={{ \'--h\': b.value / max }} />\n          <span className="bt-lab">{b.label}</span>\n        </div>\n      ))}\n    </div>\n  );\n}\n'}
CL_OLD = 'flip ringed, each described on hover - beside the share that held. Notes fold into "How this\nis measured" in both.\n'
CL_NEW = 'flip ringed, each described on hover - beside the share that held. Notes fold into "How this\nis measured" in both.\n\n**Design step 2b: Forward Exposure and Next Observation as charts.** Forward Exposure shows the\nmodelled spread and each sensitive area\'s share (with the shoreline) as lines that draw in over\n+6, +12 and +24 h, with chips for the earliest area reached and first shoreline contact, and the\nforcing mode kept visible. Next Observation shows the recommended window large beside a bar\ntimeline of disagreement per window, the recommendation lit. Shared SVG charts are added.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 37 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 38: {len(writes)} files written, {skipped} already in place.")
